INSERT INTO master.documents (id, title, document_type, source_id, source_url, publisher, version, effective_from, effective_to, publication_date, file_path, content_hash, language, confidence, data_status) VALUES ('DOC-PMEGP-GUIDELINES-2022', 'Operational Guidelines of Prime Minister''s Employment Generation Programme (PMEGP) - Ministry of MSME', 'official_guideline', 'SRC-GOI-MSME-PMEGP', 'https://www.kviconline.gov.in/pmegpeportal/pmegphome/index.jsp', 'Ministry of MSME / KVIC', 2.0, '2022-05-13', '2027-03-31', '2022-05-13', 'data/documents/pmegp_official_guidelines_2022.md', 'sha256-a79b8f02c91834e56b4f8d22', 'en', 0.99, 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.documents (id, title, document_type, source_id, source_url, publisher, version, effective_from, effective_to, publication_date, file_path, content_hash, language, confidence, data_status) VALUES ('DOC-PMFME-GUIDELINES-2021', 'Guidelines on PM Formalisation of Micro food processing Enterprises Scheme (PMFME)', 'official_guideline', 'SRC-GOI-MOFPI-PMFME', 'https://pmfme.mofpi.gov.in/', 'Ministry of Food Processing Industries, Government of India', 1.0, '2021-01-15', '2026-03-31', '2021-01-15', 'data/documents/pmfme_official_guidelines_2021.md', 'sha256-b33c1d94f291054e7a8910cd', 'en', 0.99, 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.documents (id, title, document_type, source_id, source_url, publisher, version, effective_from, effective_to, publication_date, file_path, content_hash, language, confidence, data_status) VALUES ('DOC-AHIDF-GUIDELINES-2020', 'Operational Guidelines for Animal Husbandry Infrastructure Development Fund (AHIDF)', 'official_guideline', 'SRC-GOI-DAHD-AHIDF', 'https://ahidf.udyamimitra.in/', 'Department of Animal Husbandry & Dairying, GoI', 1.0, '2020-07-20', '2027-03-31', '2020-07-20', 'data/documents/ahidf_official_guidelines_2020.md', 'sha256-c55d2e09b38712a14e9f78ba', 'en', 0.98, 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.document_chunks (id, document_id, chunk_index, chunk_text, page_number, section, embedding, embedding_model, embedding_dimension, embedding_status, metadata, data_status) VALUES ('CHK-PMEGP-01', 'DOC-PMEGP-GUIDELINES-2022', 1, 'PMEGP Quantum of Assistance: In rural areas, general category beneficiaries are entitled to a 25% margin money subsidy of the total project cost. For special categories including Women, SC, ST, OBC, Minorities, and Ex-Servicemen, the rural margin money subsidy is 35%. The beneficiary''s own contribution is 10% for general category and 5% for special categories. The maximum cost of the project eligible for subsidy is Rs 50 Lakhs for manufacturing units and Rs 20 Lakhs for service sector units.', 4, 'Quantum and Nature of Financial Assistance', NULL, 'text-embedding-004', 768, 'pending', '{"scheme": "PMEGP", "topic": "subsidy_rates", "applicable_area": "rural"}', 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.document_chunks (id, document_id, chunk_index, chunk_text, page_number, section, embedding, embedding_model, embedding_dimension, embedding_status, metadata, data_status) VALUES ('CHK-PMEGP-02', 'DOC-PMEGP-GUIDELINES-2022', 2, 'Eligibility Conditions for PMEGP Beneficiaries: Any individual above 18 years of age is eligible. There are no income ceilings for setting up projects. For setting up of project costing above Rs 10 Lakhs in the manufacturing sector and above Rs 5 Lakhs in the business/service sector, the beneficiary must possess at least VIII standard pass educational qualification. Assistance is available only for greenfield new projects.', 6, 'Eligibility Conditions', NULL, 'text-embedding-004', 768, 'pending', '{"scheme": "PMEGP", "topic": "eligibility", "qualification": "VIII Pass for >10L Mfg"}', 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.document_chunks (id, document_id, chunk_index, chunk_text, page_number, section, embedding, embedding_model, embedding_dimension, embedding_status, metadata, data_status) VALUES ('CHK-PMFME-01', 'DOC-PMFME-GUIDELINES-2021', 1, 'PMFME Credit-Linked Capital Subsidy: Support to individual micro-enterprises is provided through a credit-linked capital subsidy of 35% of eligible project cost with a maximum ceiling of Rs 10.0 Lakh per unit. The beneficiary''s minimum equity contribution must be 10% of the project cost, with the balance financed as a commercial term loan by financial institutions.', 8, 'Credit-Linked Subsidy for Micro-enterprises', NULL, 'text-embedding-004', 768, 'pending', '{"scheme": "PMFME", "topic": "subsidy_ceiling", "max_subsidy": "10 Lakh"}', 'official') ON CONFLICT (id) DO NOTHING;
INSERT INTO master.document_chunks (id, document_id, chunk_index, chunk_text, page_number, section, embedding, embedding_model, embedding_dimension, embedding_status, metadata, data_status) VALUES ('CHK-AHIDF-01', 'DOC-AHIDF-GUIDELINES-2020', 1, 'AHIDF Interest Subvention & Credit Guarantee: Under AHIDF, the Government of India provides an interest subvention of 3.0% per annum on the term loan for all eligible borrowing entities for up to 8 years. A credit guarantee fund of Rs 750 Crore is established by NABARD and managed by NABSanrakshan to provide guarantee coverage up to 25% of the credit facility sanctioned to MSMEs.', 5, 'Financial Assistance and Subvention', NULL, 'text-embedding-004', 768, 'pending', '{"scheme": "AHIDF", "topic": "interest_subvention", "rate": "3.0%"}', 'official') ON CONFLICT (id) DO NOTHING;
